from pathlib import Path
import json,collections,hashlib,html,itertools,re,math
R=Path(__file__).resolve().parent;P=R.parent
def read(n):return json.loads((R/n).read_text())
def save(n,x):(R/n).write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding='utf-8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
e=lambda x:html.escape(str(x))
cov=read('COVERAGE.json');contrasts=read('CONTRASTS.json');primary=read('PRIMARY.json');events=read('EVENTS.json');focal=read('FOCAL-chEol.json');alts=read('FOCAL-ALTERNATES.json');meta=read('SOURCE-ROWS-METADATA.json')
for pp,h in read('FREEZE.json').items():assert sha(Path(pp))==h
def D(c):
 n=sum(c.values());return sum(a*b for va,a in c.items() for vb,b in c.items() if va!=vb)/(n*(n-1)) if n>=2 else None
checked=0
for z in contrasts:
 selected=[x for x in events if all(x[k]==z[k] for k in ['reading','section','hand','variety']) and (z['view']=='all_runs' or x['runs']==1)];d=collections.defaultdict(collections.Counter)
 for x in selected:d[(x['page'],x['skeleton'],x['role'])][tuple(x['lengths'])]+=1
 for cell in z['samepage_cells']:
  for ro,field in [('paragraph','D_paragraph'),('label','D_label')]:
   val=D(d[(cell['page'],cell['skeleton'],ro)]);old=cell[field];assert (val is None and old is None) or abs(val-old)<1e-12
  checked+=1
for z in cov:
 for ro,cc in z['coverage'].items():assert cc['e_tokens']==sum(x['role']==ro and all(x[k]==z[k] for k in ['reading','section','hand','variety']) for x in events)
assert all(z['eligible_cells']==0 and z['inference']['p'] is None for z in primary)
assert not any(x['word']=='cheeeol' for x in focal)
assert collections.Counter(x['word'] for x in focal if x['reading']=='H' and x['section']=='Recipes' and x['role']=='paragraph')=={'cheol':38,'cheeol':1}
assert collections.Counter(x['word'] for x in focal if x['reading']=='F' and x['section']=='Recipes' and x['role']=='paragraph')=={'cheol':34,'cheeol':1}
assert not any(x['reading'] in ['H','F'] and x['role']=='label' for x in focal)
save('VERIFICATION.json',dict(frozen_hashes_unchanged=True,cell_diversities_independently_recomputed=checked,coverage_event_counts_reconciled=True,all4primary_contrasts_unestimable=True,focal_counts_verified=True,focal_label_comparator_absent=True,cheeeol_absent_from_readable_focal_events=True,semantic_values_assigned=0))
summary=dict(result='No supported recipe paragraph-versus-label variation effect: strict same-source-page/panel comparisons are not estimable in Recipes H or F. This is a coverage/support result, not evidence of equality.',primary=primary,focal_recipe={'H':{'cheol':38,'cheeol':1,'cheeeol':0},'F':{'cheol':34,'cheeol':1,'cheeeol':0}},focal_note='No chEol skeleton token occurs in defined L/S label rows in H or F. cheeeol is absent from all available reading-code complete-token focal records. Literal parsed transcription counts, not image-adjudicated glyph counts.',samepage_control='Only one supported all-runs comparison in any known H/F hand/section/variety stratum: H bath f82v otEdy, paragraph2 variants1+2 and label2 variants1+2; D1 vsD1, gap0. F has no supported control cell.',pooled_hint='H Recipes shEol: paragraph18sheol+4sheeol versus2labelsheol. Dparagraph.311688/Dlabel0, but two labels on different pages; secondary descriptive fallback only, cannot control page setting and not reproduced with F label data.',other_pooled_controls='H bath pooledotEdy paragraph diversity.4573,label.6667. H hand4astronomy three supported skeletons have mixed signs; no generalparagraph-greater pattern.',limits='No counting/numeral or fixed-label interpretation established. e is an EVA symbol, not expert glyph adjudication. No U/V substitution for absent F labels. No zero-run collapse or new skeleton chosen after results.',next='Inspect specific repeated same-skeleton label tokens in images / improve label transcription coverage before stronger inference. An e-run count can be retained as a structural feature; no semantic counting model is promoted.')
save('FINDINGS.json',summary)
body='<h1>E-run variation · paragraph versus label</h1><p><b>The proposed controlled comparison is not estimable in Recipes.</b> No word pattern has at least two complete paragraph tokens and two complete label tokens on the same source page/panel, in either H or F. There is no positive counting result and no evidence of equality from that lack of support.</p><p>The execution rules were frozen before e-run counts. H/F remain separate. All other known hand/section/variety cohorts are separate descriptive controls. The atlas section name Recipes is retained as metadata (including the small-plant/pharmaceutical folios); Starred paragraphs is a distinct section and is not silently substituted for it.</p>'
body+='<h2>The illustrative three-form family needs correcting</h2><table><tr><th>Recipes paragraph text</th><th>cheol</th><th>cheeol</th><th>cheeeol</th><th>Same-family L/S label tokens</th></tr>'
for code in ['H','F']:
 cc=collections.Counter(z['word'] for z in focal if z['reading']==code and z['section']=='Recipes' and z['role']=='paragraph');body+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in [code,cc['cheol'],cc['cheeol'],cc['cheeeol'],0])+'</tr>'
body+='</table><p>The cheeol occurrence is f88v.P2.9, agreed by H/F (and present in L). Across the entire parsed source, all available reading codes have no fully readable cheeeol token in this exact chEol family. The earlier three-form example was illustrative, not an attested three-step series. H has169cheol and9cheeol across all source formats/sections; F154 and10. Those global totals are not independent manuscript occurrences to be pooled.</p><details><summary>f88v.P2.9 · all alternate readings</summary>'
for z in alts['f88v.P2.9']:body+='<p>'+e(z['reading']+': '+z['raw'])+'</p>'
body+='</details><p>Labels mean source L/S codes in this audit, not every short text or diagram inscription. Circular text, captions and ambiguous X rows are excluded; their focal words remain in the full source inventory without being relabelled as plant/star names.</p>'
body+='<h2>Coverage is the constraint</h2><table><tr><th>Reading / section / hand</th><th>Paragraph readable / e-bearing</th><th>Label readable / e-bearing</th><th>Label pages</th></tr>'
for z in cov:
 if z['section'] not in ['Recipes','Balneological','Astronomy/Astrology','Starred paragraphs']:continue
 a=z['coverage']['paragraph'];b=z['coverage']['label'];body+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in [z['reading']+' · '+z['section']+' · '+z['hand'],str(a['readable'])+' / '+str(a['e_tokens']),str(b['readable'])+' / '+str(b['e_tokens']),b['pages']])+'</tr>'
body+='</table><p>H Recipes supplies148readable label tokens,36with at least one e-run; F supplies one readable label token with no e-run. H bath has19e-bearing label tokens, F5. Starred paragraphs has no defined L/S label rows in H/F. These coverage differences prevent a both-reading paragraph/label claim. A same-hand cross-section comparison would still mix section and format.</p>'
body+='<h2>What was counted</h2><p>Each maximal nonempty e-run is replaced by E, leaving all other symbols and run positions intact: cheol/cheeol share chEol; cheeedeeol becomes chEdEol with length vector(3,2). chol stays separate. No ch/sh collapse, sound values, zero-e merging or unknown repairs. e denotes literal EVA transcription, not an adjudicated manuscript glyph.</p><p>Variation is the unbiased probability that two distinct observed tokens of the same pattern have different run-length vectors: D=1−Σnᵥ(nᵥ−1)/(N(N−1)). Unlike the number of distinct variants, its expectation does not rise merely because one format has more tokens. Precision still depends on sample size, and repeated/copied or correlated tokens remain possible.</p><p>Main view includes all nonempty-run vectors; the predeclared sensitivity restricts to exactly one e-run. Both H/F Recipes views have zero supported same-page cells, so no inferential p-value was produced. Formal tests were limited in advance to Recipes H/F×two views, with leaf clustering and Bonferroni4 had support existed. No p-value was salvaged by moving to another panel or merging pages.</p>'
body+='<h2>The only strict comparison elsewhere</h2><p>H bath f82v, otEdy: paragraph has otedy once and oteedy once; label has otedy once and oteedy once. Both D=1, difference0. One cell on one leaf cannot establish a general format effect. Every other H/F known-hand/section/variety stratum lacks a supported same-page cell under these rules.</p>'
body+='<h2>Pooled hints retained, with the page control removed</h2><p>Pooling within the same section, hand and variety—but across pages—produces only a few comparable patterns. These are descriptive fallback records, not replacements for the failed feasibility gate.</p><table><tr><th>H cohort</th><th>Pattern</th><th>Paragraph N / D</th><th>Label N / D</th><th>Gap</th></tr>'
for z in contrasts:
 if z['view']!='all_runs':continue
 for cc in z['crosspage_same_stratum']:body+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in [z['section']+' hand'+z['hand'],cc['skeleton'],f"{cc['paragraph_n']} / {cc['D_paragraph']:.3f}",f"{cc['label_n']} / {cc['D_label']:.3f}",f"{cc['gap']:+.3f}"])+'</tr>'
body+='</table><p>The sole Recipes hint is shEol:18sheol+4sheeol in paragraph text versus two labels, both sheol. Two labels cannot show much variability reliably: two tokens drawn without replacement from that paragraph inventory would agree about68.8% of the time. That is an illustration of sparse information, not a format-association test. The two label sources are f89r2.L1.3 and f89v2.L1.4; page effects remain uncontrolled. F has no matching e-bearing label data. Bath points in the opposite pooled direction; the astronomy patterns have mixed signs.</p><p>Long e-runs are not confined to paragraph rows: H Recipes label f99v.L2.1 reads oeeesary, with a3-e run. That does not settle its function, but a long run alone is not evidence of counting in paragraph text.</p>'
body+='<h2>Qualification and practical outcome</h2><p>Before manuscript scores, known one-/multiple-/zero-run examples were checked; diversity agreed with direct unordered-pair enumeration for124binary token samples. Exact enumeration of equal-distribution samples of sizes3and2 gives expected format gap0. A12-leaf planted difference passes the predeclared sign-flip correction; reverse and all-zero controls do not. Exact orbit tail ranks obey their bound. These qualify arithmetic and a strong synthetic signal, not real-data power or numeral interpretation.</p><p>Every saved cell diversity and coverage event count was independently recomputed. Unknown readings and all focal alternatives remain available. No image adjudication or historical names/sounds were fitted. The result is limited support for the proposed experiment, not failure of all e-run hypotheses.</p><p>The next useful evidence would be repeated, image-checked label forms with adequate transcription coverage in the same hand and page context. This audit does not promote a semantic counting model or substitute another attractive word family.</p><h2>Full records</h2>'
for n in ['PROTOCOL.json','FREEZE.json','QUALIFICATION.json','COVERAGE.json','PRIMARY.json','CONTRASTS.json','EVENTS.json','SOURCE-ROWS-METADATA.json','SHARED-LOCUS-METADATA.json','FOCAL-chEol.json','FOCAL-ALTERNATES.json','FINDINGS.json','VERIFICATION.json']:
 body+='<p><a href="'+n+'">'+n+'</a></p>'
(R/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>E-run format audit · Reed v95</title><style>body{font:17px system-ui;line-height:1.6;max-width:1100px;margin:40px auto;padding:0 20px;background:#f6f2e8;color:#173c38}table{border-collapse:collapse;width:100%;font-size:15px}td,th{border:1px solid #abc;padding:8px;text-align:left}h1,h2{line-height:1.2}h2{margin-top:2em}details{padding:10px;border-bottom:1px solid #abc}a{color:#126151}</style>'+body+'</html>',encoding='utf-8')
save('SHA256SUMS.json',{p.name:sha(p) for p in R.iterdir() if p.is_file() and p.name!='SHA256SUMS.json'});print('Counts, coverage and diversity verified. Report saved; HTML appearance unreviewed.')
